contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(
        uint64 n1,
        uint64 t1,
        uint256 b1,
        bytes32 h1,
        uint64 s1,
        bytes32 bh1,
        uint256 o1,
        uint256 sc1,
        uint64 n2,
        uint64 t2,
        uint256 b2,
        bytes32 h2,
        uint64 s2,
        bytes32 bh2,
        uint256 o2,
        uint256 sc2
    ) public {
        uint64 numberBefore = c.number(); if (__ESBMC_reverted()) return;
        uint64 timestampBefore = c.timestamp(); if (__ESBMC_reverted()) return;
        uint256 basefeeBefore = c.basefee(); if (__ESBMC_reverted()) return;
        bytes32 hashBefore = c.hash(); if (__ESBMC_reverted()) return;
        uint64 seqBefore = c.sequenceNumber(); if (__ESBMC_reverted()) return;
        bytes32 batcherBefore = c.batcherHash(); if (__ESBMC_reverted()) return;
        uint256 overheadBefore = c.l1FeeOverhead(); if (__ESBMC_reverted()) return;
        uint256 scalarBefore = c.l1FeeScalar(); if (__ESBMC_reverted()) return;
        uint256 balBefore = address(c).balance;

        bool r1;
        c.setL1BlockValues(n1, t1, b1, h1, s1, bh1, o1, sc1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { r1 = true; } else { r1 = false; }

        bool r2;
        c.setL1BlockValues(n2, t2, b2, h2, s2, bh2, o2, sc2); bool __rev1 = __ESBMC_reverted(); if (__rev1) { r2 = true; } else { r2 = false; }

        assert(
            r1 && r2 &&
            c.number() == numberBefore &&
            c.timestamp() == timestampBefore &&
            c.basefee() == basefeeBefore &&
            c.hash() == hashBefore &&
            c.sequenceNumber() == seqBefore &&
            c.batcherHash() == batcherBefore &&
            c.l1FeeOverhead() == overheadBefore &&
            c.l1FeeScalar() == scalarBefore &&
            address(c).balance == balBefore
        );
    }
    receive() external payable {}
}

