pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 n1, uint64 t1, uint256 b1, bytes32 h1, uint64 s1, bytes32 bh1, uint256 o1, uint256 sc1, uint64 n2, uint64 t2, uint256 b2, bytes32 h2, uint64 s2, bytes32 bh2, uint256 o2, uint256 sc2) internal {
        uint64 numberBefore;
        try c.number() returns (uint64 __r) { numberBefore = __r; } catch { return; }
        uint64 timestampBefore;
        try c.timestamp() returns (uint64 __r) { timestampBefore = __r; } catch { return; }
        uint256 basefeeBefore;
        try c.basefee() returns (uint256 __r) { basefeeBefore = __r; } catch { return; }
        bytes32 hashBefore;
        try c.hash() returns (bytes32 __r) { hashBefore = __r; } catch { return; }
        uint64 seqBefore;
        try c.sequenceNumber() returns (uint64 __r) { seqBefore = __r; } catch { return; }
        bytes32 batcherBefore;
        try c.batcherHash() returns (bytes32 __r) { batcherBefore = __r; } catch { return; }
        uint256 overheadBefore;
        try c.l1FeeOverhead() returns (uint256 __r) { overheadBefore = __r; } catch { return; }
        uint256 scalarBefore;
        try c.l1FeeScalar() returns (uint256 __r) { scalarBefore = __r; } catch { return; }
        uint256 balBefore = address(c).balance;
        bool r1;
        try c.setL1BlockValues(n1, t1, b1, h1, s1, bh1, o1, sc1) { r1 = false; } catch { r1 = true; }
        bool r2;
        try c.setL1BlockValues(n2, t2, b2, h2, s2, bh2, o2, sc2) { r2 = false; } catch { r2 = true; }
        assertTrue(r1 && r2 &&
            c.number() == numberBefore &&
            c.timestamp() == timestampBefore &&
            c.basefee() == basefeeBefore &&
            c.hash() == hashBefore &&
            c.sequenceNumber() == seqBefore &&
            c.batcherHash() == batcherBefore &&
            c.l1FeeOverhead() == overheadBefore &&
            c.l1FeeScalar() == scalarBefore &&
            address(c).balance == balBefore);
    }

    function testFuzz_run(uint64 n1, uint64 t1, uint256 b1, bytes32 h1, uint64 s1, bytes32 bh1, uint256 o1, uint256 sc1, uint64 n2, uint64 t2, uint256 b2, bytes32 h2, uint64 s2, bytes32 bh2, uint256 o2, uint256 sc2) public {
        _run(n1, t1, b1, h1, s1, bh1, o1, sc1, n2, t2, b2, h2, s2, bh2, o2, sc2);
    }

    receive() external payable {}
}
